using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainEffectWithMultiplierCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/GainEffectWithMultiplierCustomDescription", order = 0)]
public class GainEffectWithMultiplierCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string text = "";
		text = battleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLast();
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), text, rawLocalizedDescription);
	}

	public string GetActionDescription(string amountModified, BattleAction battleActionToGetDescription, BattleAction battleActionToGetEffectDescription)
	{
		string rawLocalizedDescription = GetRawLocalizedDescription(battleActionToGetDescription);
		string text = "";
		text = battleActionToGetEffectDescription.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLast();
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), text, rawLocalizedDescription);
	}
}
